        item.scopeType ? `范围 ${item.scopeType}` : null
      ]
        .filter(Boolean)
        .join(" · ") || "未返回命中条件"
    )
  );
}

function HintList({ hints, emptyText }) {
  if (!hints || !hints.length) {
    return h("p", { className: "empty-copy" }, emptyText || "暂无提示");
  }
  return h(
    "div",
    { className: "hint-list" },
    hints.map((hint, index) =>
      h(
        "article",
        { key: `${hint.code || "hint"}-${index}`, className: "hint-card" },
        h("strong", null, hint.title || hint.code || "提示"),
        h("p", null, hint.detail || "")
      )
    )
  );
}

function PreviewSidePanel({ title, result, fallbackText }) {
  const activities = (result && result.activities) || [];
  const queryModeLabel = result && result.queryMode === "SKU" ? "按 SKU 维度预览" : "按商品维度预览";
  const statusLabel = result && result.available === false ? "结果暂不可用" : result && result.hit ? "已命中" : "未命中";

  return h(
    "section",
    { className: "preview-side" },
    h(
      "div",
      { className: "preview-side-head" },
      h("div", null, h("h3", null, title), h("p", null, result && result.summary ? result.summary : fallbackText)),
      h("span", { className: result && result.hit ? "preview-badge is-hit" : "preview-badge" }, statusLabel)
    ),
    h("p", { className: "preview-mode" }, queryModeLabel),
    result && result.reasonMessage ? h("p", { className: "preview-reason" }, result.reasonMessage) : null,
    activities.length
      ? h(
          "div",
          { className: "activity-list" },
          activities.map((item, index) => h(ActivitySummary, { key: `${item.activityId || title}-${index}`, item }))
        )
      : h("div", { className: "preview-empty" }, h("strong", null, "未返回命中活动"), h("p", null, fallbackText)),
    h(HintList, {
      hints: result && result.hints,
      emptyText: "当前侧无额外排查提示"
    })
  );
}

function PreviewPanel({ previewResult, pending, onSubmit, preview, updatePreview }) {
  const data = previewResult && previewResult.data && previewResult.data.data;
  const querySummary = data && data.querySummary;
  const summaryText = querySummary
    ? [
        querySummary.regionCode ? `区域 ${querySummary.regionCode}` : null,
        querySummary.productId ? `商品 ${querySummary.productId}` : null,
        querySummary.skuId ? `SKU ${querySummary.skuId}` : null,
        querySummary.scopeType ? `范围 ${querySummary.scopeType}` : null,
        querySummary.queryMode === "SKU" ? "按 SKU 维度预览" : "按商品维度预览"
      ]
        .filter(Boolean)
        .join(" · ")
    : "输入单商品或单 SKU 条件，查看管理配置侧与用户运行侧命中结果。";

  return h(
    Section,
    {
      id: "preview",
      title: "活动命中预览",
      actions: h(
        "button",
        { type: "button", className: "primary", disabled: pending, onClick: onSubmit },
        pending ? "预览中" : "发起预览"
      )
    },
    h("p", { className: "section-intro" }, summaryText),
    h(
      "div",
      { className: "form-grid" },
      h(Field, { label: "商品 ID" }, h(TextInput, { value: preview.productId, onChange: (value) => updatePreview("productId", value), placeholder: "必填" })),
      h(Field, { label: "SKU ID" }, h(TextInput, { value: preview.skuId, onChange: (value) => updatePreview("skuId", value), placeholder: "可选，非空时优先按 SKU" })),
      h(
        Field,
        { label: "活动范围类型" },
        h(SelectInput, {
          value: preview.scopeType,
          onChange: (value) => updatePreview("scopeType", value),
          options: [
            { value: "", label: "全部范围" },
            { value: "ALL", label: "ALL" },
            { value: "CATEGORY", label: "CATEGORY" },
            { value: "SKU_LIST", label: "SKU_LIST" }
          ]
        })
      ),
      h(Field, { label: "说明" }, h("div", { className: "preview-note" }, preview.skuId ? "当前将按 SKU 维度优先预览。" : "当前未填写 SKU，将按商品维度预览。"))
    ),
    data
      ? h(
          "div",
          { className: "preview-results" },
          h(PreviewSidePanel, {
            title: "管理配置侧",
            result: data.managementResult,
            fallbackText: "请检查活动范围绑定、区域配置和活动状态。"
          }),
          h(PreviewSidePanel, {
            title: "用户运行侧",
            result: data.runtimeResult,
            fallbackText: "如无命中，可能尚未上线、生效或同步完成。"
          }),
          h(
            "section",
            { className: "preview-diff" },
            h("h3", null, "差异提示"),
            h(HintList, {
              hints: data.diffHints,
              emptyText: "当前双侧未发现额外差异。"
            })
          )
        )
      : h(
          "div",
          { className: "preview-empty-state" },
          h("strong", null, "尚未发起预览"),
          h("p", null, "这里会展示管理配置侧、用户运行侧以及双侧差异提示。")
        )
  );
}

